fn hash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
}
fn vnoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = hash(i);
  let b = hash(i + vec2f(1.0, 0.0));
  let c = hash(i + vec2f(0.0, 1.0));
  let d = hash(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
fn effect(uv: vec2f, t: f32) -> vec4f {
  let p = uv * vec2f(rexx.size.x / rexx.size.y, 1.0) * params.scale + vec2f(t * params.drift, 0.0);
  var v = 0.0;
  var amp = 0.5;
  var q = p;
  // four octaves of fractional Brownian motion: a constant-bounded loop
  for (var i = 0; i < 4; i++) {
    v += amp * vnoise(q + vec2f(0.0, t * 0.3));
    q *= 2.0;
    amp *= 0.5;
  }
  let col = mix(params.dark.rgb, params.light.rgb, v);
  return vec4f(col, 1.0);  // an opaque generator: straight == premultiplied at alpha 1
}
